import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.Dj7FWXx_.js";const k=JSON.parse('{"title":"获取 QQ 等级加速面板","description":"","frontmatter":{},"headers":[],"relativePath":"api/get_level_tasks.md","filePath":"api/get_level_tasks.md","lastUpdated":null}'),d={name:"api/get_level_tasks.md"};function l(o,e,n,h,c,r){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="获取-qq-等级加速面板" tabindex="-1">获取 QQ 等级加速面板 <a class="header-anchor" href="#获取-qq-等级加速面板" aria-label="Permalink to &quot;获取 QQ 等级加速面板&quot;">​</a></h1><p><code>get_level_tasks</code> 刷新并返回当前 Android Bot 的 QQ 等级加速面板；调用不执行游戏。</p><p>“来元宝P图一次”当前暂不支持。</p><p>返回内容只保留免费等级任务。会员推广项目及日常、额外分类中标记为会员或付费、或引导开通/购买权益的任务会在框架源头移除；会员签到属于框架提供的免费领取任务，只出现在完整管理面板的 <code>member_info.member_task_list</code> 中。</p><p>普通任务的 <code>available</code> 表示当前框架是否支持该任务，<code>can_execute</code> 表示本次是否仍可执行。任务当天已经完成时，<code>available</code> 仍为 <code>true</code>，而 <code>can_execute</code> 为 <code>false</code>；客户端应显示“已完成”，不能显示成“暂不支持”。<code>available=false</code> 才表示当前框架不支持该任务。</p><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>self_id</td><td>number</td><td>是</td><td>在线 Bot QQ 号</td></tr></tbody></table><p>SDK 使用 <code>api.forProtocol(&#39;android&#39;).get_level_tasks(self_id)</code>；原位置参数不变。仅 <code>center_task_id=80</code> 且标题为“创建小游戏擂台并取得成绩”的任务增加 <code>available/executable</code>、<code>can_execute</code>、<code>status_text/execution_message</code>。框架能力决定未来自动计划，不再以外部 worker 安装为前置；当前完成状态和执行互斥决定本次能否执行，失败原因单独显示。查询只刷新，不触发分数上报；执行时由 Go 直接协议为方块冲刺 v6 上报 1–99 随机整数分数。</p><p>v2.3.1 起，擂台任务取消每日尝试次数限制。只有 QQ 刷新确认完成才显示“已完成”；执行失败返回错误原因，面板显示“待完成”，允许再次执行。擂台任务不再返回 <code>attempted_today</code>，客户端应以 <code>can_execute</code> 判断本次能否执行。正在执行时保留账号互斥，禁止并发提交；每次新执行重新核验 QQ 状态、当前登录材料和新建条件，不续传旧房间分数。SDK 和页面刷新不自动重试。</p><h2 id="返回" tabindex="-1">返回 <a class="header-anchor" href="#返回" aria-label="Permalink to &quot;返回&quot;">​</a></h2><p>保持 <code>uin</code>、<code>overall_info</code>、<code>base_info</code>、<code>extra_info</code>、<code>is_freeze</code> 等面板字段；不再返回会员推广项目。QQ 的 <code>is_done</code>、成绩及加速数值不由本地记录生成。失败时 SDK 拒绝 Promise。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> panel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forProtocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;android&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get_level_tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> tasks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> panel.extra_info?.extra_task_list </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []</span></span></code></pre></div><p>v2.3.0 的擂台扩展使用 Go 模式直接协议上报方块冲刺 v6 的 1–99 随机整数分数，已在 Linux amd64 测试站通过 2082083 的标准任务验收；无新增分数、游戏或计时参数。每日尝试门槛与授权提示见<a href="https://github.com/Carlor-Official/Mengka-NT/blob/v2.3.9/docs/arena-level-task.md" target="_blank" rel="noreferrer">小游戏擂台等级任务</a>。</p>`,13)])])}const _=a(d,[["render",l]]);export{k as __pageData,_ as default};
